#!/usr/bin/env bash
# write-image-values.sh <chart> <output file> <image tag> <environment>
#
# Writes the Helm values file that points a chart at the CI-built images
#   ghcr.io/<owner>/forge-<name>:<tag>
#   chart forge            -> gateway.image, web.image          (values-<env>-images.yaml)
#   chart forge-inference  -> gpuExporter.image                 (values-images.yaml)
# Only registry/repository/tag are set; everything else (pullPolicy, ...) keeps the
# chart default. Used by ci.yaml (dev bump) and promote.yaml (prod promotion).
# OWNER defaults to the repository owner, lower-cased (registry names must be lower case).
set -euo pipefail

chart="$1"
out="$2"
tag="$3"
env="$4"
owner="$(echo "${OWNER:-${GITHUB_REPOSITORY_OWNER:?}}" | tr '[:upper:]' '[:lower:]')"

# Only allow tags that look like "sha-<hex>" so nothing odd can be written into YAML.
if ! [[ "$tag" =~ ^sha-[0-9a-f]{7,40}$ ]]; then
  echo "refusing unexpected image tag: $tag" >&2
  exit 1
fi

image() { # $1 = values key, $2 = image name
  printf '%s:\n  image:\n    registry: ghcr.io\n    repository: %s/%s\n    tag: "%s"\n' "$1" "$owner" "$2" "$tag"
}

case "$chart" in
  forge)
    body="$(image gateway forge-gateway; image web forge-web)"
    ;;
  forge-inference)
    body="$(image gpuExporter forge-gpu-exporter)"
    ;;
  *)
    echo "unknown chart: $chart (expected forge or forge-inference)" >&2
    exit 1
    ;;
esac

name="$(basename "$out")"
{
  echo "# ${name} - which builds of Forge's images ${env} runs."
  echo "# GENERATED by .github/scripts/write-image-values.sh - do not edit by hand."
  echo "# Images built by CI from commit ${tag#sha-}."
  echo "$body"
} > "$out"

cat "$out"
